function bfs(start, adj) {
  const visited = new Set();
  const queue = [start];
  while (queue.length > 0) {
    const v = queue.shift();
    if (visited.has(v)) continue;   // marked on DEQUEUE — too late
    visited.add(v);
    console.log(v);
    for (const u of adj[v]) {
      queue.push(u);                // pushed without checking visited
    }
  }
}
